SELECT vendedor, monto, ROW_NUMBER() OVER (ORDER BY monto DESC, vendedor) as rn, RANK() OVER (ORDER BY monto DESC, vendedor) as rk, DENSE_RANK() OVER (ORDER BY monto DESC, vendedor) as dr FROM ventas ORDER BY monto DESC, vendedor;
